{"command": "cd /tmp/sv-0126e6938ad744deb209f0b08e04f8c7/advanced-multi-complexity && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (name, tfm, pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
for key in sorted(set(b.keys()) | set(a.keys())):
    bv = b.get(key)
    av = a.get(key)
    if bv != av:
        changes.append((key, bv, av))
    else:
        unchanged.append((key, bv))

print('=== CHANGES ===')
for (proj, tfm, pkg), bv, av in changes:
    print(f'{proj:20s} {tfm:12s} {pkg:50s} {bv or \"N/A\":>10s} -> {av or \"N/A\":>10s}')

print(f'\n=== UNCHANGED ({len(unchanged)} packages) ===')
for (proj, tfm, pkg), v in unchanged:
    print(f'{proj:20s} {tfm:12s} {pkg:50s} {v}')
"", "description": "Compare baseline vs after"}
